changeSet.sql:
DROP INDEX IF EXISTS clinlims.uq_test_terminology_mapping_test;
DROP INDEX IF EXISTS clinlims.uq_test_terminology_mapping_component;
CREATE UNIQUE INDEX uq_test_terminology_mapping_test
    ON clinlims.test_terminology_mapping (test_id, source, code)
 WHERE component_id IS NULL AND sample_type_id IS NULL;
CREATE UNIQUE INDEX uq_test_terminology_mapping_component
    ON clinlims.test_terminology_mapping (test_id, component_id, source, code)
 WHERE component_id IS NOT NULL AND sample_type_id IS NULL;
CREATE UNIQUE INDEX uq_test_terminology_mapping_sample_type
    ON clinlims.test_terminology_mapping (test_id, sample_type_id, source, code)
 WHERE component_id IS NULL AND sample_type_id IS NOT NULL;
CREATE UNIQUE INDEX uq_test_terminology_mapping_component_sample_type
    ON clinlims.test_terminology_mapping (test_id, component_id, sample_type_id, source, code)
 WHERE component_id IS NOT NULL AND sample_type_id IS NOT NULL;

rollback.sql:
DROP INDEX IF EXISTS clinlims.uq_test_terminology_mapping_sample_type;
DROP INDEX IF EXISTS clinlims.uq_test_terminology_mapping_component_sample_type;
DROP INDEX IF EXISTS clinlims.uq_test_terminology_mapping_test;
DROP INDEX IF EXISTS clinlims.uq_test_terminology_mapping_component;
CREATE UNIQUE INDEX uq_test_terminology_mapping_test
    ON clinlims.test_terminology_mapping (test_id, source, code)
 WHERE component_id IS NULL;
CREATE UNIQUE INDEX uq_test_terminology_mapping_component
    ON clinlims.test_terminology_mapping (test_id, component_id, source, code)
 WHERE component_id IS NOT NULL;
